window.KV_LOAD&&KV_LOAD(278,{"file": "KinhVoLuongTho10_278.docx", "blocks": [{"p": "PHẬT THUYẾT ĐẠI THỪA VÔ LƯỢNG THỌ"}, {"p": "TRANG NGHIÊM THANH TỊNH BÌNH ĐẲNG GIÁC KINH"}, {"p": "Người giảng: Lão Pháp Sư Tịnh Không"}, {"p": "Tập 278"}, {"h": "Kinh văn", "add": 1}, {"p": "Kinh văn: “Vị đắc A Duy Việt Trí giả, tất đắc A Duy Việt Trí”."}, {"p": "Từ câu Kinh văn này mà xem. Hôm qua giảng đến “đắc quả tự tại ”. Thế Tôn ở trên Kinh nêu ra với chúng ta tứ quả của Tiểu Thừa. Chúng ta xem lại câu Kinh văn này, đây là chú ý vào A La Hán. “Vị đắc A Duy Việt Trí giả, tất đắc A Duy Việt Trí ”. Ở đây nói là quả của Đại Thừa, A Duy Việt Trí Bồ Tát, cổ Đại đức ở trong chú sớ đã nói với chúng ta, là thất địa trở lên. Từ đây mà thấy, Thế giới Tây Phương Cực Lạc là thuần nhất Đại Thừa, không những thuần nhất Đại Thừa, trên thực tế là nhất Phật Thừa. Cổ Đại đức thời đại Tùy Đường đã chú thích, thời đại giáo hóa này của Phật Thích Ca Mâu Ni có Tiểu Thừa có Đại Thừa, ở trong Đại Thừa vẫn còn có một thừa. “Sở dĩ duy hữu nhất thừa pháp, vô nhị diệc vô tam, trừ Phật phương tiện thuyết ”. Đây là đem bổn nguyện giáo hóa chúng sanh của chư Phật Như Lai, bao gồm cả Pháp Thân Đại Sĩ ứng hóa trong chín pháp giới nói ra với chúng ta rồi. Từ đây mà thấy, Tiểu thừa Thanh Văn, Duyên Giác, Quyền Giáo Bồ Tát đều là Như Lai giáo hóa chúng sanh mà phương tiện nói, không phải thật sự nói. Mục đích thật sự là hy vọng tất cả chúng sanh đều có thể trong một đời này viên thành Phật đạo, mọi người đều chứng được Phật quả cứu cánh viên mãn. Tại vì sao phải nói Tam Thừa? Tam Thừa là thuộc về bất đắc dĩ mà phương tiện nói. Chúng sanh không có cái căn tánh này, không có chí hướng lớn như vậy, việc tu hành có người thì nói tôi chỉ cần cuộc đời này có thể bình an vô sự thì được rồi, những thứ khác tôi đều không mong cầu gì cả, kiểu người như vậy thì Phật cũng hết cách đối với họ. Họ không muốn thành Phật, họ cũng không muốn thành Bồ Tát, thậm chí bạn nói quả vị Tu Đà Hoàn họ cũng không có hứng thú, họ chỉ hy vọng có thể sống cuộc đời bình an vô sự thì họ đã rất mãn nguyện rồi. Nhưng mà Phật đối với tất cả chúng sanh tuyệt đối sẽ không để họ bị thất vọng, bạn hy vọng điều gì, các Ngài liền giúp đỡ bạn đạt được điều đó, bởi vì “Phật thị môn trung hữu cầu tất ứng ”. Bạn hy vọng làm một người tốt, các Ngài sẽ giúp bạn; bạn muốn sanh thiên thì các Ngài cũng có thể giúp đỡ bạn, khẳng định là có thể viên mãn nguyện vọng của tất cả chúng sanh. Đây là Phật từ bi đến cùng cực. Cho nên pháp môn của Phật cũng rất nhiều, đều là vì ứng cơ mà thiết lập ra."}, {"p": "Chúng ta biết Thế giới Tây Phương Cực Lạc là Nhất Phật Thừa, ở đâu còn có Tiểu Thừa nữa chứ? Cho nên ở chỗ này nói với chúng ta cũng là phương tiện nói, không phải chân thật nói. Thế giới Tây Phương Cực Lạc không có nhân thiên, cũng không có Thanh Văn, Duyên Giác. Vì sao Phật ở trên Tịnh Độ Kinh đều nói với chúng ta thiên nhân, Thanh Văn chúng? Chúng ta phải hiểu cái ý của Ngài, tuyệt đại đa số người ở Thế giới Tây Phương Cực Lạc là đới nghiệp vãng sanh (việc này không giống như những thế giới khác), mà đới nghiệp vãng sanh là mang theo nghiệp mà đi, cũng như tại Thế giới Ta Bà này của chúng ta, những thứ phiền não tập khí này là mang theo mà đi đến bên đó, đương nhiên phải đoạn phiền não, phải đoạn tập khí. Phiền não, tập khí không đoạn, bạn làm sao có thể thành tựu? Khẳng định không thể thành tựu. Nhưng Thế giới Tây Phương không giống với tất cả Sát Độ khác của chư Phật, tuy là phiền não tập khí của bạn không có đoạn, bạn đến Thế giới Tây Phương Cực Lạc, trí huệ của bạn, năng lực của bạn (cái năng lực này chính là thần thông mà chúng ta thường nói), thọ dụng của bạn (chúng ta thường nói là phước báo) đều giống như Phật A Di Đà. Việc này không thể nghĩ bàn."}, {"p": "Bạn là phàm phu, bạn làm sao mà có thể ngang bằng phước báo với Phật? Việc này trên Kinh mọi người đã đọc thấy rất rõ ràng, thứ nhất là đến Thế giới Tây Phương Cực Lạc thì dung mạo giống như Phật, thân thể giống như Phật, là thân tử ma chân kim sắc. Thế giới Tây Phương là thế giới bình đẳng, sanh đến bên đó thì giống y như Phật, trí huệ thần thông đạo lực hết thảy đều như nhau, nói cách khác bạn đã thành Phật rồi. Nhưng việc thành Phật này không phải là nhờ khả năng của bạn, không phải do bạn tu chứng được, mà là do đâu? Là do bổn nguyện của Phật A Di Đà gia trì cho bạn, hay nói cách khác là hưởng phước báo của Phật A Di Đà. Cũng giống như người thế gian này của chúng ta, một đứa trẻ đi đầu thai. Nếu đầu thai vào nhà vua chúa, nó vừa mới sinh ra thì đã được thân phận là Thái tử, sự thọ dụng của nó cũng không thua với Hoàng đế. Đó không phải là có được do năng lực của bản thân nó, mà là do cha của nó cho nó, là sự việc giống như vậy. Cho nên chúng ta đến Thế giới Tây Phương Cực Lạc, phước báo chúng ta cũng giống như tất cả chư Phật, thần thông trí huệ năng lực đều như nhau, không phải do tự mình tu mà là Phật A Di Đà cho. Việc này thật không thể nghĩ bàn. Đây là sự thù thắng chỉ có ở Thế giới Tây Phương Cực Lạc, tha phương thế giới hết thảy đều không có."}, {"p": "Tuy là Phật cho chúng ta trí huệ thần thông đạo lực, vậy phiền não tập khí của chúng ta có còn cần phải đoạn hay không? Đương nhiên phải đoạn. Nếu như bạn chưa đoạn, thì cứ hưởng thụ phước báo mà người khác ban cho bạn. Đến khi bạn chính mình đoạn tận phiền não rồi, thì cái phước báo đó mới từ tự tánh của bạn mà lưu lộ ra, thì mới không phải là Phật A Di Đà cho bạn. Chúng ta phải hiểu đạo lý này, phải hiểu hoàn cảnh chân thật của Thế giới Tây Phương Cực Lạc."}, {"p": "Ở chỗ này nói thiên nhân, nói Tiểu Thừa, nói A Duy Việt Trí Bồ Tát, đều là công phu chính mình thực tế tu hành đoạn chứng khi đến nơi đó. Ở Thế giới Tây Phương Cực Lạc công phu đoạn chứng bằng với Tu Đà Hoàn, Tư Đà Hàm của Tây Phương Cực Lạc Thế giới. Đoạn chứng đồng nghĩa với việc năng lực thần thông trí huệ trên thực tế của bạn không có một Thanh Văn, Duyên Giác, Quyền Giáo Bồ Tát nào ở Tha Phương Thế Giới có thể so sánh được. Việc này chúng ta không thể không biết. Cho nên trong chú giải của người xưa cũng nói, trên thực tế mỗi một người vãng sanh đều là phát Bồ Đề tâm, đều là nhất hướng chuyên niệm, vì vậy Thế giới Tây Phương Cực Lạc là Nhất Thừa Pháp, Nhất Phật Thừa, cái gọi là Thanh Văn, nhân, thiên chỉ là thị hiện mức độ đoạn hoặc, là tùy thuận sự tương đối của tha phương mà nói. Chúng ta hiểu được chân tướng sự thật này."}, {"p": "Ở chỗ này chúng ta lại phải lưu ý, “Kinh Vô Lượng Thọ” chúng ta vẫn còn chưa đọc đến tam bối vãng sanh, vãng sanh chánh nhân. Hai phẩm Kinh văn này nói rõ vãng sanh Thế giới Tây Phương Cực Lạc thì phải có đủ những điều kiện gì. Trên Kinh đã nói với chúng ta rất rõ ràng, rất minh bạch: “Phát Bồ Đề tâm, nhất hướng chuyên niệm ”. Câu nói này rất là quan trọng. Bạn xem, thượng phẩm vãng sanh là điều kiện này, trung phẩm hạ phẩm hết thảy đều là điều kiện này, quyết định không thể nào xem nhẹ."}, {"p": "Nhưng hiện nay, tôi thường nghe thấy ở Hồng Kông, ở Đài Loan, ở Mỹ, đại khái ở Singapore cũng có, từ Nhật Bản truyền đến bổn nguyện niệm Phật. Bổn nguyện niệm Phật này ngày xưa Tổ sư Đại đức truyền thừa không có sai, nhưng truyền đến ngày nay, tôi nghe họ nói với tôi thì thấy có vấn đề, vì họ chỉ xem trọng nguyện thứ 18 trong số 48 nguyện, họ nói nguyện thứ 18 là bổn nguyện, những nguyện khác đều không cần học. Nguyện thứ 18 là gì? Mười niệm được sanh, cho nên họ mỗi ngày họ chỉ niệm mười câu Phật hiệu thôi, tương lai nhất định được vãng sanh, trên Kinh đã nói mà! Đến lúc lâm chung không thể vãng sanh thì sẽ trách móc Phật A Di Đà, Phật A Di Đà Ngài nói mà không giữ lời, con y theo phương pháp mười niệm của Ngài mà vì sao con không thể vãng sanh? Kỳ thực những người này là tự cho mình thông minh, đầu cơ trục lợi, đối với ý nghĩa của 48 lời nguyện họ đều không hiểu, đã hiểu sai cái ý của Phật. Phật không hề nói sai, mà do bạn đã nghe sai, đã hiểu sai, lỗi lầm ở bạn, không phải ở Phật. Chư Tổ sư Đại đức ngày xưa đã nói rất rõ ràng rất minh bạch, 48 nguyện, mỗi một nguyện đều bao gồm 47 nguyện còn lại một cách viên mãn, thiếu một nguyện thì nguyện này của Ngài không viên mãn, có khiếm khuyết, chính là ở trên “Kinh Hoa Nghiêm” đã nói “một tức là nhiều, nhiều tức là một ”, sao bạn lại có thể chấp trước một niệm trong 48 nguyện? Việc này là không thể. Phải nên hiểu rằng, người xưa nói nhất nguyện chính là nhất thiết nguyện, vậy thì đúng, bất kỳ một nguyện nào cũng đều bao gồm tất cả nguyện, vậy mới là viên mãn, mới là không sai. Nguyện thứ mười chín là “phát Bồ Đề tâm ”. Thực tế mà nói, trong 48 nguyện thì hai nguyện này quan trọng nhất, chúng ta ở trong ba bậc vãng sanh là thượng trung hạ đều có câu này. “Phát Bồ Đề tâm ” là nguyện thứ mười chín, “nhất hướng chuyên niệm ” là nguyện thứ mười tám. Nếu bạn chỉ có nhất hướng chuyên niệm mà không có phát Bồ Đề tâm thì bạn không thể vãng sanh, vì vậy mà người niệm Phật rất nhiều, người được vãng sanh thì lại không nhiều. Đạo lý này chúng ta không thể không hiểu. Chân tướng sự thật đều bày ở trước mắt chúng ta."}, {"p": "Năm xưa, tôi học Phật ở Đài Trung, lão sư Lý thường hay nhắc nhở chúng tôi, hiện tại trong một vạn người niệm Phật thật sự có thể vãng sanh thì chỉ có hai - ba người mà thôi, chỉ hai - ba phần vạn mà thôi. Vậy những người còn lại, thật sự là trong một vạn người có hơn 9.990 người đều không thể vãng sanh, là hơn 9.990 người không thể vãng sanh. Nguyên nhân là gì? Là không có phát Bồ Đề tâm, bạn không có tương ưng với bổn nguyện của Phật A Di Đà. Nếu bạn không phát Bồ Đề tâm mà đến Thế giới Tây Phương Cực Lạc, Thế giới Tây Phương Cực Lạc thì không phải là Nhất Phật Thừa. Thế giới bên đó là Nhất Phật Thừa thì phát Bồ Đề tâm quan trọng hơn bất cứ thứ gì."}, {"p": "Thế nào gọi là “Bồ Đề tâm”?"}, {"p": "Trong các Kinh luận đã có nói rất nhiều, cũng không dễ hiểu. Trong “Quán Vô Lượng Thọ Phật Kinh” đã nói với chúng ta, chí thành tâm, thâm tâm, hồi hướng phát nguyện tâm, nói ba cái này. Vì sao mà “Bồ Đề tâm” là ba cái này? Ba cái nhưng thực tế là một cái. Thể của “Bồ Đề tâm” là chí thành tâm, chí thành tâm khởi tác dụng, cái tác dụng đó có cái đối với mình, có cái đối với người. Đối với chính mình là thâm tâm, đối với người thì là hồi hướng phát nguyện tâm, cho nên thâm tâm cùng với hồi hướng phát nguyện tâm là tác dụng của “Bồ Đề tâm”. Một cái là tác dụng đối với bản thân, một cái là tác dụng đối với người khác. Trên thực tế là một cái tâm mà nói từ ba phương diện."}, {"p": "Nếu như cái này không dễ hiểu, chúng ta hãy xem lại “Đại Thừa Khởi Tín Luận”. Trong “Đại Thừa Khởi Tín Luận”, Mã Minh Bồ Tát đã nói với chúng ta về “Bồ Đề tâm”, Ngài nói là “trực tâm, thâm tâm và đại bi tâm ”. Chúng ta đem Kinh và Luận hợp lại mà xem thì sẽ dễ dàng hiểu được ý nghĩa. Trên luận thì nói là trực tâm, trên Kinh thì nói chính là chí thành tâm, thâm tâm thì cũng giống như vậy. Trên Kinh nói hồi hướng phát nguyện tâm chính là trên luận nói đại bi tâm, đại từ đại bi. Như vậy thì chúng ta sẽ dễ hiểu hơn. Nhưng mà thâm tâm vẫn còn khá khó hiểu, rốt cuộc thì cái gì gọi là thâm tâm? Thâm tâm là tự thọ dụng, “Bồ Đề tâm” khởi tác dụng là tự thọ dụng."}, {"p": "Năm xưa, khi tôi còn ở Mỹ, đã đem cái “Bồ Đề tâm” này viết thành năm điều gồm mười chữ: Chân thành (chân thành chính là chí thành tâm, chính là trực tâm), thanh tịnh, bình đẳng, chánh giác (chính là thâm tâm), từ bi, như vậy thì mọi người sẽ dễ hiểu hơn nhiều. Từ bi tâm chính là hồi hướng phát nguyện tâm, là đối với người, còn đối với chính mình thì phải thanh tịnh - bình đẳng - chánh giác. Chúng ta khởi tâm động niệm lời nói việc làm mà tương ưng với mười chữ này, thì bạn đã thật sự phát “Bồ Đề tâm”. Đây là vô thượng “Bồ Đề tâm”. Nếu đã thật sự phát tâm thì trong một đời này nhất định sẽ sanh đến Thế giới Tây Phương Cực Lạc, nhất định sẽ được thân cận Phật A Di Đà. Nếu quả nhiên bạn có nguyện vọng như vậy, thì từ nay trở đi, bạn sinh hoạt, làm việc xử sự đối người tiếp vật, bạn nhất định phải dùng chân tâm, không thể lại dùng vọng tâm nữa."}, {"p": "Có lẽ có người sẽ hỏi, tôi dùng chân tâm đối đãi người, người khác dùng vọng tâm đối với tôi, vậy không phải tôi đã bị thiệt thòi lớn rồi hay sao? Vào lúc này thì bạn phải hỏi rằng: Bạn muốn tiếp tục ở lại trong lục đạo luân hồi hay là muốn đến Thế giới Cực Lạc? Nếu như là đến Thế giới Cực Lạc thì bạn không dùng chân tâm thì không được, ở Thế giới Cực Lạc người người đều dùng chân tâm, không có ai dùng vọng tâm. Bạn vẫn còn không chịu dùng chân tâm, vẫn dùng cái tâm hư vọng để xử sự đối người tiếp vật, thì bạn niệm Phật hết cả cuộc đời này cũng không thể vãng sanh, bạn là người nằm trong số lượng hơn 9.990 người trong một vạn người đó. Nếu bạn chịu dùng chân tâm, thì bạn nằm trong số hai, ba người trong một vạn người đó. Đạo lý này các vị phải nên hiểu, phải nên hiểu rõ cái chân tướng sự thật. Cho nên chúng ta chân thật phát tâm hành Bồ Tát đạo, nhất định phải thấy được Phật A Di Đà. Chúng ta không sợ người khác lừa gạt mình, người khác lừa gạt ta, sỉ nhục ta, ức hiếp ta, thực ra mà nói ta đều rất cung kính mà cảm kích đối với họ, niệm A Di Đà Phật rồi hồi hướng cho họ. Vì sao vậy? Vì đã tiêu nghiệp chướng cho ta, là việc tốt mà! Họ tự mình tạo tội nghiệp thay ta tiêu nghiệp chướng, họ thật sự là đã xả mình vì ta, họ là ân nhân của ta. Bản thân họ không biết, ta thì thấy rõ ràng tường tận. Ta và họ không đi chung một con đường. Họ đi đó là đường sáu nẻo luân hồi, là đi ba đường ác đạo, còn ta đi con đường nhất Thừa Phật đạo, không phải Thanh Văn, không phải Duyên Giác, cũng không phải Bồ Tát, đường ta đi là con đường thành Phật. Hy vọng mọi người có được sự nhận biết như vậy, tiền đồ của chúng ta là một mảng quang minh, sáng lạn. Nhất định không tham muốn hưởng thụ danh văn lợi dưỡng trong một đời này, phải đem nó xả bỏ thật sạch sẽ."}, {"p": "Khi tôi rời khỏi Singapore đi đến Úc Châu, đã viết một bức đối liễn để khuyến khích chính mình, cũng là khuyến khích các đồng học chúng ta. Đối liễn này ghi là: “Xứ nghịch cảnh, tùy ác duyên, vô sân hận, nghiệp chướng tận tiêu”. Nghịch cảnh là hoàn cảnh của chúng ta không tốt, chỗ nào cũng đều là chướng ngại, hoàn cảnh nhân sự không tốt, người hủy báng chúng ta rất nhiều, người nhiễu điều sinh sự rất nhiều. Sống trong hoàn cảnh như vậy nhất định không có một niệm tâm sân hận, là “vô sân hận, nghiệp chướng tận tiêu ”. Có một niệm tâm sân hận thì nghiệp chướng của bạn hiện tiền, cái quả đó là kết cái quả oan oan tương báo không bao giờ dứt. Điều này không thể được. Cho nên ở phương diện này, nếu chúng ta bị oan ức, hãm hại của người khác, thì lập tức phải nghĩ đến Phật Thích Ca Mâu Ni khi xưa tu nhẫn nhục Ba La Mật đã gặp vua Ca Lợi, chúng ta hãy nghĩ đến việc Nhẫn Nhục tiên nhân đã gặp vua Ca Lợi. Cái tai họa như vậy cũng có thể nhận chịu được mà không có một chút sân hận nào, cũng không có một chút tâm muốn báo thù. Chúng ta phải học. Không có tâm sân hận thì nhẫn nhục Ba La Mật đã viên mãn, không có một ý niệm muốn báo thù thì giới điều không sát sanh đã viên mãn. Cho nên vua Ca Lợi đã có công đức rất lớn, đã thành tựu cho người tu hành hai sự việc lớn. Cũng giống như nói bạn tu hành người ta đến khảo nghiệm bạn, thử thách khảo nghiệm bạn, xem công phu của bạn như thế nào. Chúng ta có thể nói chỉ trong một chút là đã bị người ta khảo đảo mất, vậy thì xong rồi, vậy thì vẫn phải tiếp tục trong tam đồ lục đạo. Nếu muốn không bị đánh rớt, ta hết thảy đều có thể nhận chịu, tiếp nhận một cách hoan hỷ, không có sân hận, không có báo thù, trái lại còn cảm niệm ân đức, sự khảo nghiệm này cho biết được công phu và cảnh giới tu học của bạn. Cho nên đối với nghịch cảnh ác duyên, chúng ta phải thật sự là bội phần cảm kích, vì đã làm cho cảnh giới của mình không ngừng nâng cao."}, {"p": "Câu đối kế tiếp là “Xứ thuận cảnh, tùy thiện duyên, vô tham si, phước huệ toàn hiện”. Hoàn cảnh tốt, tất cả đều rất như ý thì “vô tham si”. Đáng sợ nhất là trong cảnh giới này bạn khởi cái tâm tham lên, bạn bị cảnh giới mê hoặc, vậy thì bạn xong rồi. Nhất định phải không có tham, không có ngu si, “phước huệ toàn hiện”, phước huệ liền hiện tiền."}, {"p": "Đây là chúng ta tự mình khuyến khích chính mình, cũng là khuyến khích hết thảy đồng học, dù trong thuận cảnh hay nghịch cảnh cũng lìa tham sân si. Tham sân si là tam độc. Khởi tâm động niệm nếu như tương ưng với tam độc phiền não, thì đây là tạo nghiệp của súc sanh, ngạ quỷ, địa ngục, tương lai quả báo là ở trong tam đồ, cho nên nhất định là không thể được. Khởi tâm động niệm lời nói việc làm, chúng ta nhất định là không quản chuyện người khác, nên quản cho tốt bản thân mình. Người khác có làm thế nào thì cũng không liên quan gì đến mình, đó là việc của họ. Chúng ta thì nhất định tùy thuận theo giáo huấn của Phật Đà, nhất định phải tùy thuận thập thiện, phải tùy thuận tam quy y. Tam quy là giác, chánh, tịnh. Phải tùy thuận lục độ, tùy thuận Bồ Đề tâm, đại Bồ Đề tâm. Như vậy một lòng xưng niệm cầu sanh Tây Phương thì không có một ai mà không vãng sanh. Xưa kia, Tổ sư Đại đức đã nói rằng: “Pháp môn này vạn người tu vạn người đi ”. Có thể tu học được như lý như pháp thì người người đều vãng sanh, cho nên nhất định phải tương ưng với chân thành, thanh tịnh, bình đẳng, chánh giác, từ bi, đặc biệt là tâm từ bi."}, {"p": "Tâm từ bi là đối với những ai? Là đối với oan gia trái chủ, bạn có thể từ bi đối với người hãm hại bạn, thì bạn đối với tất cả chúng sanh cũng sẽ từ bi. Đối với tam đồ lục đạo, chúng sanh địa ngục, những người không từ việc ác nào đều phải đại từ đại bi, họ thật đáng thương, ngu si, đã tạo tác tội nghiệp. Nếu như họ có trí huệ, thì họ tuyệt đối sẽ không tạo tội nghiệp. Cho nên chúng ta đối với người, đối với tất cả chúng sanh hữu tình, trong cách nhìn thì quan trọng nhất là phải khẳng định tánh bổn thiện, chân tánh của tất cả mọi chúng sanh. Chân tánh là Phật tánh, tất cả chúng sanh đều có Phật tánh. Phật tánh thì vốn thiện, họ vì sao mà lại tạo ác? Bởi vì họ đã mê mất đi bổn tánh. Đã mê mất bổn tánh mà lại tùy thuận tập khí, tập tính thì bất thiện. Phải nên biết đạo lý này. Cho nên Phật nhìn tất cả chúng sanh thấy đều là Phật, các Ngài nhìn như thế nào? Nhìn bổn tánh. Cho nên tất cả chúng sanh đều đáng để cho ta tôn kính, đều đáng để ta cúng dường, đều đáng để cho ta phụng sự một cách toàn tâm toàn lực, đạo lý là ở chỗ này. Phật nhìn là chính xác, phàm phu chúng ta nhìn người thì sai lệch mất rồi. Không nhìn vào từ chính diện mà nhìn từ phiến diện, không nhìn bổn tánh của họ mà nhìn vào tập tánh của họ, vậy thì sai rồi. Phật Bồ Tát nhìn vào bổn tánh của tất cả chúng sanh, không nhìn tập tánh của họ, cho nên tâm của các Ngài vĩnh viễn là tương ưng với chân thành - thanh tịnh - bình đẳng - chánh giác - từ bi, đạo lý chính là chỗ này. Đây là điều mà chúng ta cần phải học tập. Đây là con đường để thành Phật."}, {"p": "Hôm nay giảng câu “A Duy Việt Trí ” này, A Duy Việt Trí ở trong “Kinh Di Đà” thì nói là A Bệ Bạt Trí, bởi vì đây là dịch âm từ tiếng Phạn, âm dịch có khác một chút, cho nên đây là một sự việc, một danh từ. Ý nghĩa là, cổ Đức nói “bất thối chuyển ư thành Phật chi đạo ”, chính là đi con đường thành Phật này, họ một mạch thẳng tiến, họ sẽ không bị thối lui trở lại. A Bệ Bạt Trí là ý nghĩa như vậy. Kinh tiểu bổn thì dịch là A Bệ Bạt Trí, cổ Đức có người dịch từ trên Kinh văn. A dịch là Vô."}, {"p": "Trong chữ “A Di Đà Phật”, từ đầu tiên cũng dịch là Vô, Di Đà dịch là Lượng, là vô lượng, Phật dịch là Giác. Vì vậy ý nghĩa của chữ A Di Đà Phật toàn bộ dịch ra từ tiếng Phạn nghĩa là Vô Lượng Giác. Phật có ý nghĩa là giác. Phật ở trên “Kinh Di Đà” đã nói với chúng ta về ý nghĩa đó, một cái thì nói là vô lượng quang, một cái thì nói là vô lượng thọ. Ý nghĩa của hai chữ này đều rất hay. Quang là quang minh, quang minh biến chiếu, chúng ta hiện nay thì nói là không gian, vô lượng không gian. Thọ là nói thọ mạng. Thọ mạng là thời gian, người hiện nay thì nói là vô lượng thời không. Ý nghĩa của chữ A Di Đà Phật chính là vô lượng thời không. Ở trong cái vô lượng thời không đã bao gồm hết tất cả, không sót một thứ gì, cho nên danh hiệu này thì ý nghĩa không thể nghĩ bàn."}, {"p": "“A Bệ Bạt Trí” thì “Bạt Trí” dịch ra là thối chuyển, A dịch là vô, là vô thối chuyển. Cách giải thích này của cổ Đức rất rõ ràng, rất minh bạch: “Vô thối chuyển ư thành Phật chi đạo ”. Ý nghĩa này dịch rất hay. Trong “Di Đà Yếu Giải” của Ngẫu Ích Đại Sư đã nói với chúng ta ba cái bất thối, ở trong chữ A Bệ Bạt Trí có ba cái ý nghĩa, chính là ba loại bất thối."}, {"p": "Ba Loại Bất Thối Chuyển."}, {"p": "Loại thứ nhất là “Vị bất thối”, chuyển phàm thành Thánh, sẽ không bị thối chuyển thành phàm phu. Đây là ý nghĩa cạn nhất trong từ A Duy Việt Trí. Hôm qua chúng ta đã bàn đến Tu Đà Hoàn thì đã không thối chuyển rồi. Nếu bạn hỏi vì sao mà họ không thối chuyển? Trong kiến giải của họ không có sai lầm, cũng chính là nói, cách nhìn của họ đối với thế xuất thế gian pháp, đối với người, đối với việc, đối với vật chính xác, không có sai lầm, cho nên họ không bị thối chuyển. Chúng ta thì vì sao lại bị thối chuyển? Chúng ta đối với tất cả người sự vật sự việc, cách nhìn đã bị sai rồi. Sai ở chỗ nào? Ở chỗ hành động theo cảm tính, đều là tùy thuận theo tập khí phiền não của chính mình, tùy thuận theo sự yêu ghét của chính mình, cái này thì tôi thích, cái kia thì tôi ghét, vậy thì không được. Ưa thích và chán ghét thì không có ở trong bổn tánh, ở trong bổn tánh thì không có yêu thương cũng không có chán ghét. Việc này thì phải nên biết. Cho nên Phật Bồ Tát, người tu hành tùy thuận pháp tánh, tùy thuận chân tánh. Ở trong chân tánh không có thất tình ngũ dục, phải hiểu cái đạo lý này. Thất tình ngũ dục, tham sân si mạn là từ trong vô minh mà sinh ra, từ trong tâm thức, trong vọng tâm mà sinh ra, chân tâm thì không có. Ở trong chân tâm thì chỉ có chân thành - thanh tịnh - bình đẳng - chánh giác - từ bi, cái này thì trong chân tâm có. Ở trong vọng tâm thì mới có phiền não tập khí, mới có yêu ghét, mới có tham sân si. Việc này nhất định phải rõ ràng, phải minh bạch."}, {"p": "Loại thứ hai là “hạnh bất thối”. Đây là nói hầu hết Bồ Tát Đại Thừa, Bồ Tát Đại Thừa phát nguyện độ chúng sanh, điều đầu tiên ở trong tứ hoằng thệ nguyện là “chúng sanh vô biên thệ nguyện độ ”. Các Ngài nói được các Ngài làm được, nhất định là không có thối chuyển thành Tiểu Thừa. Tiểu Thừa là tự độ mà không độ tha, là chỉ tự lo cho chính mình, không lo cho người khác. Những lời này phải nói cho rõ ràng, không nói rõ ràng e rằng mọi người nghe sẽ hiểu lầm. Tiểu Thừa có thật sự là không độ cho người khác sao? Họ cũng độ người, họ độ những người nào? Tôi thấy anh vừa mắt thì tôi độ anh, thấy không vừa mắt thì tôi không độ, cho nên họ chưa có “Bồ Đề tâm”. Cho nên có duyên với họ thì họ sẽ độ bạn, không có duyên thì họ không độ bạn, vả lại bạn còn phải đi tìm họ, đi thỉnh giáo với họ, họ mới dạy bạn. Bạn không đi tìm họ, họ sẽ không đến tìm bạn. Việc này không giống với Bồ Tát Đại Thừa. Bồ Tát Đại Thừa giáo hóa chúng sanh không có yêu cầu điều kiện, dùng lời hiện nay mà nói đó là đa nguyên văn hóa. Họ không phân biệt quốc tịch, không phân chủng tộc, cũng không phân tín ngưỡng, họ không có yêu cầu bất kỳ điều kiện gì, vả lại còn chủ động đến tìm bạn, không nhất định bạn phải đi tìm họ, họ sẽ đến tìm bạn. Đây là Bồ Tát Đại Thừa."}, {"p": "Ở trong pháp Đại Thừa cũng thường nói Phật không độ người không có duyên, vậy Phật có đi tìm những chúng sanh không có duyên đó để giúp đỡ họ, để độ họ không? Phật sẽ đi tìm. Phật tìm như thế nào? Những người này không chịu nghe theo giáo huấn của Phật, đây chính là không có duyên với Phật. Bạn phải hiểu ý nghĩa này, thì bạn sẽ để tâm tỉ mỉ mà quan sát, bạn tư duy, hiện tại có rất nhiều người đã thọ tam quy, đã thọ ngũ giới, thậm chí là đã thọ Tam Đàn Đại Giới của người xuất gia, họ có nghe theo giáo huấn của Phật hay không? Không nghe, vẫn cứ tùy thuận phiền não của chính mình. Đó đều là người không có duyên. Người không có duyên nhưng Phật cũng chăm lo cho họ, vì thế Phật chăm lo cho chúng sanh là bình đẳng. Còn chúng sanh có học Phật hay không, có nghe theo giáo huấn của Phật hay không, có y giáo phụng hành hay không, đó chính là một người thì có duyên, một người thì không có duyên. Người có duyên thì thật sự nghe, thật sự tin, thật sự y giáo phụng hành, đây là người có duyên. Có duyên thì trong một đời này khẳng định sẽ thành tựu. Đây chính là nói có duyên thì được độ, không có duyên thì không thể được độ. Cách nói như vậy của tôi mọi người nghe sẽ dễ hiểu hơn. Tuyệt đối không phải là nói người không có duyên thì Phật không màng tới họ, không có vị Phật nào như vậy. Có A La Hán như vậy, chứ không có vị Phật nào như vậy, Bồ Tát cũng không như vậy. Bồ Tát đối với những người không có duyên, người không có chủng tánh Phật thì gieo cho họ chủng tử Phật, người có chủng tử Phật rồi thì giúp họ tăng trưởng thêm. Đây đều là trong đời này không thể độ được họ, nhưng đã tăng trưởng thêm, giúp đỡ họ thành thục. Thành thục thì sẽ được độ."}, {"p": "Chỗ này những điều mà tôi nói với các vị, chúng ta ở trong cuộc sống, công việc, xử sự đối người tiếp vật thì chúng ta dùng chân tâm, nhất định tuân theo giáo huấn của Phật Đà. Chúng ta lấy tâm chân thành đối đãi người, nhất định không có giả dối hư ngụy. Chúng ta lấy tâm thanh tịnh để tiếp vật, quyết định không có ô nhiễm. Cái tâm thanh tịnh này chính là vừa mới nói ở trong nghịch cảnh ác duyên không khởi sân hận, ở trong thuận cảnh thiện duyên không khởi tham si, thì bạn sẽ không bị cảnh giới bên ngoài làm ô nhiễm, sẽ không bị cảnh giới lay chuyển, vĩnh viễn giữ gìn tâm địa thanh tịnh bình đẳng. Bình đẳng chính là không có cao thấp, tuyệt đối không có việc ta hơn người khác, người khác không bằng ta, đây gọi là tâm cao thấp, như vậy thì không có bình đẳng. Chân tâm là bình đẳng, không những bình đẳng đối với tất cả người mà đối với tất cả động vật cũng bình đẳng, đối với tất cả quỷ thần cũng bình đẳng."}, {"p": "Hiện tại thế gian này rất loạn, yêu ma quỷ quái rất nhiều, phải nên biết quỷ thần dù là thiên thần (thiên thần thì vẫn là phàm phu) cũng kém xa với Tu Đà Hoàn. Tu Đà Hoàn đã nhập vào hàng Thánh nhân, thật sự là Thánh nhân. Thiên thần như Đại Phạm Thiên Vương, Ma Hê Thủ La Thiên Vương thì vẫn là phàm phu. Việc này chúng ta phải hiểu được. Phiền não tập khí của họ vẫn chưa đoạn được phẩm nào, không khác gì chúng ta cả, chỉ có điều là phước báo lớn hơn ta, họ sanh lên trời để hưởng thiên phước. Do đó, họ tuy rằng có ngũ thông, ngũ thông có tác dụng gì? Tham sân si mạn chưa có đoạn trừ, danh văn lợi dưỡng chưa có đoạn dứt, những thiên thần quỷ thần này, hiện tại trên thế gian rất nhiều, tôi gặp được cũng không ít, quyết định không thể bị họ lừa gạt. Nếu bạn bị họ lừa gạt, bạn bị mắc lừa, thì con đường của bạn đi là con đường của quỷ thần chứ không phải đi con đường Phật Bồ Tát, trong đời tương lai của bạn, sau khi chết đi rồi sẽ đi vào quỷ thần đạo, thiệt thòi rất lớn. Bạn đi vào quỷ thần đạo, quỷ thần sẽ xem thường bạn. Chúng ta đi là Bồ Tát đạo, đi là Phật đạo, thì quỷ thần tôn kính bạn, quỷ thần bảo hộ bạn. Đây là đạo lý nhất định."}, {"p": "Có một số đồng học đến hỏi tôi, vì họ thường hay tiếp xúc với các nhà ngoại cảm, Trung Quốc có nhà ngoại cảm, ngoại quốc cũng có nhà ngoại cảm, nước Mỹ có mấy nhà ngoại cảm đã được quốc tế thừa nhận, họ biết được rất nhiều những việc mà người thế gian chúng ta không biết được, nhưng mà họ không có phương pháp nào để giải quyết. Đây chính là nói biết nó như vậy nhưng không biết vì sao lại như vậy. Phương pháp để giải quyết vẫn là phải tìm ở trong Phật môn, cho nên quỷ thần đến tìm tôi rất nhiều. Tôi đã làm lễ tam quy y cho họ, khi mà họ có vấn đề khó khăn, thì tôi giúp họ giải quyết. Quả thực có rất nhiều quỷ thần cũng rất thông minh, vừa nói với họ thì liền hiểu ngay, họ liền hiểu được. Cho nên nhất định không nên để cho quỷ thần lừa gạt. Người bị người lừa gạt thì còn chấp nhận được, bị quỷ thần lừa gạt thì không thể chấp nhận được, quá ngu si rồi. Quỷ thần gặp chúng ta thì chúng ta còn phải dạy họ là khác, chúng ta là thầy của họ. Những đạo lý và sự thật này đều nên thông đạt, đều nên rõ ràng."}, {"p": "Thế gian vẫn còn có một số người thông minh, đã lợi dụng những người ngu si (người ngu si rất nhiều), tin tưởng quỷ thần, khiếp sợ quỷ thần, thì liền cố tình giả thần giả quỷ để lừa gạt những tín đồ lương thiện trong xã hội. Mục đích là gì vậy? Mục đích là cầu danh văn lợi dưỡng cho bản thân."}, {"p": "Hai mươi mấy năm trước, khoảng năm 1977, lần đầu tiên tôi đi đến Hồng Kông giảng Kinh, nghe được các đồng tu Hồng Kông bên đó nói với tôi, có một vị pháp sư thích dùng thần thông để tiếp dẫn chúng sanh. Thần thông của ông làm sao mà có được vậy? Ông đi tìm một số phóng viên tin tức, tìm một số biên tập viên của tạp chí, tặng tiền cho họ, nhờ họ đăng lên trên các tờ báo và tạp chí, nói rằng vị pháp sư này có thần thông. Sau khi thổi phồng lên như vậy xong, tên tuổi của pháp sư liền nổi tiếng, rằng vị pháp sư này không phải người phàm, ông có thần thông. Thần thông của ông là do tin tức chế tạo mà ra, phiền phức về sau sẽ rất lớn. Những phóng viên tin tức đều không phải dễ đối phó, thường hay đến hỏi xin ông tiền bạc, nếu ông không cho thì họ sẽ vạch trần những chuyện này. Họ làm đến nỗi vị pháp sư ấy không thể sống nổi ở Hồng Kông, đành rời khỏi Hồng Kông, đi đến Mỹ. Đến Mỹ ông vẫn tiếp tục làm như vậy, làm đến mức rất có tiếng tăm. Đây là những người thông minh, thế gian pháp thì chúng ta thường nói là thông minh quá bị thông minh hại. Nghe nói vị pháp sư này hiện tại cũng đã mất rồi. Có người kể với tôi khi ông ra đi có thoại tướng rất là xấu. Đương nhiên là không tốt rồi, vì đã nghĩ hết mọi cách để nhũng nhiễu sinh sự lừa gạt chúng sanh thì làm gì có kết quả tốt chứ? Trồng thiện nhân thì được thiện quả, cái nhân của bạn bất thiện thì làm sao bạn có quả báo tốt được? Những sự việc như vậy thì rất nhiều."}, {"p": "Tôi thường hay nghe nói đến người nào đó là Bồ Tát gì đó tái lai, là Phật gì đó tái lai. Có rất nhiều đồng tu đã đến hỏi tôi: “Pháp sư à, cách nghĩ của Ngài thì như thế nào? ”. Tôi nói, tôi cũng không có cách nào. Tôi nói, tôi chỉ nghe người xưa nói rằng thân phận bị bại lộ thì liền đi ngay, thì đó là thật. Nếu như thân phận đã bị lộ, thiên hạ đều đã biết mà người đó vẫn còn ở lại, vậy thì sẽ rất là lạ, tôi sẽ cảm thấy rất là lạ. Cho nên, hiện tại lợi dụng nhà báo, lợi dụng sự truyền bá, lợi dụng nhà ngoại cảm để tạo ra những tin tức này nhằm lừa gạt chúng sanh thì quá nhiều quá nhiều, nhiều không kể xiết. Các đồng tu học Phật chúng ta tâm địa đều rất là thiện lương, nhưng không đủ trí huệ nên rất dễ bị mắc lừa, rất dễ dàng bị đánh lừa. Những người này quả thực sở trường lớn nhất của họ chính là có tài ăn nói, biết nói chuyện, họ có tà tri tà kiến, có tà trí huệ. Trên thực tế chúng ta tỉ mỉ mà suy nghĩ, đại loại đều là con cháu của Ma Vương đến thế gian này để nhiễu loạn Phật pháp, thấy những người niệm Phật có được cái tâm tốt, trong đời này sẽ vãng sanh, liền nhanh chóng lôi họ trở lại. Đây là nhiệm vụ mà họ đến thế gian này, là do Ma Vương đã phái đến. Việc này ở trên Kinh có ghi chép."}, {"p": "Họ tạo ra những tội này thì quả báo đều là ở A Tỳ Địa Ngục, không phải là một sự việc tốt. Đây chính là nói đã phá hoại pháp thân huệ mạng của người khác, còn nghiêm trọng hơn so với việc giết hại thân thể của họ. Giết hại họ thì không hề gì, ngạn ngữ thường nói là qua 49 ngày thì sẽ quay trở lại, họ lại đầu thai trở lại. Vì vậy sanh mạng là việc nhỏ, huệ mạng mới là việc lớn. Một người có thể gặp được Phật pháp, gặp được chánh pháp là việc mà trăm nghìn vạn kiếp khó tìm cầu. Cơ hội này thì quá khó để mà gặp được. Họ gặp được rồi, bạn lại nhẫn tâm tước đoạt mất cơ hội của họ, cái nghiệp tội này thật sự là quá nghiêm trọng, là nghiệp tội của A Tỳ Địa Ngục. Cho nên chúng ta phải nên hiểu, một Bồ Tát chân chánh thì khẳng định là sẽ thành tựu cho chúng sanh, yêu thương chúng sanh, chúng ta thường nói là họ yêu quý oan gia của họ, yêu quý kẻ đối đầu với họ, yêu quý kẻ thù của họ, yêu quý người đã tổn hại họ nghiêm trọng, họ không hề khởi một ý niệm sân hận nào, đây là Bồ Tát. Vẫn còn có cái ý niệm sân hận thì họ là phàm phu, họ không phải là Bồ Tát. Bản thân chúng ta cũng dựa vào những cảnh giới này để khám nghiệm bản thân, kiểm tra chính mình, xem sự tu hành của ta rốt cuộc đã đi vào quỹ đạo hay chưa, có chút công phu nào hay không? Ở trong cuộc sống thường ngày, gặp được những sự việc không vừa ý có còn khởi cái tâm sân hận hay không?"}, {"p": "Có một ý niệm tâm sân hận, thì cổ đức nói “không sợ niệm khởi chỉ sợ giác chậm ”, một niệm tâm sân hận vừa khởi thì lập tức phải tỉnh ngộ, ta sai rồi, ta học Phật như thế nào vậy? Làm sao mà lại thành ra như thế này? Người niệm Phật thì lập tức khởi một câu A Di Đà Phật, đem cái tâm sân hận đó loại trừ. Ở trong thuận cảnh khởi một cái tâm tham ái cũng sai rồi, đây đều là phiền não đang khởi hiện hành. Hỷ nộ ai lạc ái ố dục, thất tình ngũ dục đều là phiền não đang khởi tác dụng, khởi hiện hành. Chỉ cần những thứ này vừa mới khởi, thì lập tức dùng câu A Di Đà Phật để dẹp trừ nó. Câu A Di Đà Phật này khởi lên chính là giác. Cho nên pháp môn niệm Phật này thù thắng hơn các pháp môn khác là ở chỗ này, bởi vì bạn sẽ rất dễ dàng đề khởi lên. Bạn phải đem câu Phật hiệu này niệm cho thuần thục. Lúc nào thì khởi tác dụng? Chính là vào lúc phiền não của bạn khởi hiện hành, bạn có thể đề khởi được nó, công phu của bạn đã đắc lực, đã khởi tác dụng. Niệm Phật có nhiều hơn nữa, có niệm tốt hơn đi nữa mà phiền não hiện hành thì vẫn cứ hiện hành như cũ, vậy thì công phu của bạn không đắc lực. Hay nói cách khác, bạn căn bản là không có công phu, bạn ngày ngày niệm Phật thì cũng giống như đọc sách, ngày ngày đều học mà thi thì chỉ được điểm không, không có thành tích gì đáng nói."}, {"p": "Người học Phật công phu là ở chỗ nào? Công phu chính là phiền não vừa khởi thì nó lập tức liền bị đè xuống. Đè nén lâu rồi (lâu ở trong cái hoàn cảnh hiện tại này thì ít nhất là 10 năm), vừa khởi hiện hành thì bạn có thể phát giác, công phu như vậy bạn vận dụng được hơn 10 năm, thì tự nhiên phiền não sẽ không khởi hiện hành, lúc đó thì việc vãng sanh sẽ nắm phần chắc, lúc nào cũng có thể vãng sanh, sanh tử tự tại. Thế gian này nếu vẫn còn duyên phần, duyên phần là cái gì? Là vẫn còn có rất nhiều người muốn thân cận bạn, bạn vẫn còn có thể khuyên bảo rất nhiều người niệm Phật vãng sanh, thì bạn có thể ở thêm vài năm. Sanh tử tự tại chính là thọ mạng tự tại, muốn trụ thêm bao nhiêu năm đều không trở ngại, muốn đến khi nào đi thì lập tức liền có thể đi. Đến khi công phu được đắc thì sẽ có thể làm được. Công phu không đắc lực thì không được. Khi còn chưa đắc lực thì sẽ bị nghiệp lực xoay chuyển. Việc này rất đáng sợ. Chúng ta học Phật ít nhất cũng phải học được đến trình độ này. Chúng ta mặc dù chưa đoạn phiền não tập khí, nhưng mà sanh về Phàm Thánh Đồng Cư Độ thì tuyệt đối không vấn đề gì, khẳng định là có thể vãng sanh."}, {"p": "Tất cả pháp thế gian đều là giả, đều là trống rỗng, như một giấc mộng, phải nên hoàn toàn buông xả, buông xả tất cả thân tâm thế giới. Buông xả không phải là bảo không quan tâm nữa, không quan tâm nữa thì việc học Phật sẽ cảm thấy không hợp với lẽ đời thường, mà vẫn sống với mọi người như trước nhưng trong tâm thì nhất định không có vướng mắc, về hình thức thì quyết định không có gì khác, chung sống ôn hòa, nhưng dụng tâm thì có khác. Buông xả là buông xả ở trong tâm, không phải là nói buông xả trên sự. Có rất nhiều người nghe lời mà nghe sai rồi."}, {"p": "Năm kia, hình như có nhận được bức thư của một người từ Trung Quốc đại lục viết cho tôi, ông nói ông nghe tôi giảng Kinh nghe đến đoạn buông xả, ông liền buông xả, công việc cũng buông xả luôn. Sau khi buông xả được hai tháng thì ông không còn tiền vì không có thu nhập, ông viết thư hỏi tôi giờ phải làm sao? Bây giờ không có cách nào để lo cho cuộc sống nữa. Việc này là sai rồi. Buông xả là buông xả ở trong tâm, không phải buông xả ở trên sự, tâm địa phải thanh tịnh, chỉ có một câu Phật hiệu, cuộc sống thường ngày vẫn như xưa, công việc như xưa, xã giao như xưa, đều không ngại sự. Trên “Kinh Hoa Nghiêm” nói là “lý sự vô ngại, sự sự vô ngại ”. Ngại sự nghĩa là gì? Là vọng tưởng phân biệt chấp trước của bạn, những thứ này là ngại sự. Bạn đã triệt để buông xả rồi thì bạn đã nhập vào cảnh giới vô chướng ngại. Nếu như nói trên sự cũng buông xả, vậy thì hà cớ gì chư Phật Như Lai phải đến nơi này để độ chúng sanh? Đây không phải là đi kiếm chuyện hay sao? Đây không phải vô cớ sinh sự hay sao? Không có trở ngại, sự không có trở ngại. Lý cùng sự đều phải hiểu rõ thì học Phật mới học được viên mãn, học được một cách hạnh phúc, học được tự tại an lạc. Cho nên Bồ Tát các Ngài phải thực hiện bổn nguyện của mình, các Ngài phát thệ nguyện không phải là lời giả dối, không phải là lừa gạt người, mà nói được là làm được, thật sự là muốn thành tựu chúng sanh giúp đỡ chúng sanh, làm gì có đạo lý đi chướng ngại chúng sanh chứ? Quyết định là không có đạo lý này. Đây là hành bất thối."}, {"p": "Thứ ba là “niệm bất thối”."}, {"p": "Đây là Đại Thừa Bồ Tát. Niệm bất thối chính là như đã nói ở phía trước, niệm niệm tương ưng với “Bồ Đề tâm”, niệm niệm các Ngài hướng về là thành Phật chi đạo, khởi tâm động niệm lời nói việc làm dù là Sát Na (thời gian ấy quá ngắn tạm), thì họ vẫn không rời khỏi “Bồ Đề tâm”. “Bồ Đề tâm” chính là chân thành - thanh tịnh - bình đẳng - chánh giác - từ bi, niệm niệm đều tương ưng với điều này, đây gọi là niệm bất thối. Việc này thật không dễ dàng, cho nên Phật Bồ Tát dạy chúng ta tu pháp môn sám hối."}, {"p": "Ở trong thập nguyện của Phổ Hiền dạy chúng ta “Sám trừ nghiệp chướng”. Sám hối chính là phản tỉnh kiểm điểm. Đến lúc nào thì cầu sám hối? Không thể định ra một thời gian, mà thời thời khắc khắc phản tỉnh, thời thời khắc khắc đề cao cảnh giác. Chúng ta là phàm phu, việc này thì bản thân nhất định phải khẳng định, chúng ta không phải là Thánh nhân. Nếu đã là phàm phu thì sáu căn tiếp xúc cảnh giới sáu trần làm gì có đạo lý không khởi tâm động niệm? Khởi tâm động niệm thì không đáng sợ, đáng sợ là bạn không giác ngộ, sợ là sợ bạn tùy thuận theo ý niệm vọng tưởng của bạn, vậy thì phiền phức to rồi. Cho nên người xưa nói: “Không sợ niệm khởi, chỉ sợ giác chậm ”. Bạn phải thời thời khắc khắc mà cảnh giác, ta khởi ý niệm này, ngôn ngữ của ta, hành vi của ta có tương ưng với “Bồ Đề tâm” hay không, có tương ưng với Thập Thiện Nghiệp Đạo hay không, có tương ưng với lục độ hay không, có tương ưng với Phổ Hiền Thập Nguyện hay không? Nếu quả là tương ưng thì được rồi, bạn là đang tinh tấn ở trên đạo Bồ Đề. Nếu như không tương ưng, phải mau chóng hồi đầu. Nhất định là phải tương ưng. Không tương ưng thì nhất định là tương ưng với tham sân si mạn, với tự tư tự lợi, với danh văn lợi dưỡng. Nếu tương ưng với những thứ ấy vậy là đang tạo nghiệp tam đồ. Mười pháp giới bày ra ngay trước mắt chúng ta là mười con đường, rốt cuộc thì chúng ta đi con đường nào? Phải hướng về mục tiêu chính xác, nhất định không thể có một chút sai lầm nào, như vậy thì mới có thể làm đến được niệm bất thối. Niệm bất thối là niệm niệm đều tương ưng với Vô Thượng Bồ Đề. Cổ Đức nói niệm niệm đều lưu nhập Ta Bà khổ hải. “Ta Bà Khổ” là tiếng Phạn, ý nghĩa của nó là nhất thiết chủng trí, chính là chữ “Phật” này mà chúng tôi thường hay nói."}, {"p": "“Phật” là dịch ra từ tiếng Phạn, có hai ý nghĩa, một cái là trí huệ, một cái là giác ngộ. Trí là thể, giác là dụng. Ở trong trí thì có ba loại chủng trí, gồm có nhất thiết trí, đạo chủng trí và nhất thiết chủng trí. Niệm bất thối này mà niệm niệm tương ưng với nhất thiết chủng trí, đây là loại cao nhất, viên mãn nhất trong ba loại đã nói. Nhất thiết trí là Thanh Văn, Duyên Giác chứng được, Đạo Chủng Trí là hàng Bồ Tát chứng được, nhất thiết chủng trí là trí huệ cứu cánh viên mãn ở trên quả địa Như Lai, nó tương ưng với cái này. Cho nên niệm bất thối này, Pháp Thân Bồ Tát, ở trong “Kinh Hoa Nghiêm” thì nói Viên giáo sơ trụ chứng được niệm bất thối. Đương nhiên có niệm bất thối thì vị bất thối, hạnh bất thối hết thảy đều có. Chứng được vị bất thối thì rất hiếm thấy có hành bất thối. Hành có thể thối, niệm có thể thối, nhưng vị của họ thì không thối. Chứng được hành bất thối, niệm của họ có thối thì vị cũng không thối. Cho nên chứng được tam bất thối mới chân thật là A Duy Việt Trí, là Viên Giáo Sơ Trụ Bồ Tát, vừa mới chứng được niệm bất thối. Nhưng A Duy Việt Trí Bồ Tát, là một A Duy Việt Trí Bồ Tát thật sự thì là thất địa trở lên. Thất địa trở lên thì là bát địa. Bát địa gọi là bất động địa, chân thật là bất thối rồi. Nhưng từ thất địa trở xuống, những vị Bồ Tát này niệm vẫn còn sẽ thối, tiến tiến thối thối, nhưng họ thối đến mức thấp nhất thì cũng không thối đến Viên Giáo Sơ Trụ, Viên Giáo Sơ Trụ là mức thấp nhất của họ, sẽ không bị thối xuống nữa, khẳng định họ là Pháp Thân Đại Sĩ, họ không thể để thối mất hết pháp thân. Đây là ở trên Kinh Đại Thừa Phật thường hay dạy bảo chúng ta."}, {"p": "Tổ sư Đại đức từ xưa đến nay chú giải vãng sanh Kinh, vãng sanh Kinh chính là Tịnh Độ tam Kinh, đều là cầu vãng sanh đến Tây Phương Cực Lạc Thế giới. Cho nên, tương lai các vị xem thấy ở trong chú sớ vãng sanh Kinh của chư cổ Đức thì các vị hiểu được đây là “Kinh Vô Lượng Thọ”, “Kinh Quán Vô Lượng Thọ”, “Kinh A Di Đà”, ba bộ Kinh này đều gọi là vãng sanh Kinh. Ở trong chú giải chú thích A Duy Việt Trí đều là nói đến thất địa trở lên, cho nên việc này thật sự là không thể nghĩ bàn. Pháp môn Tịnh Độ vi diệu, ngũ nghịch thập ác mười niệm thành tựu, đới nghiệp vãng sanh, sanh về hạ hạ phẩm đều được tam bất thối. Đây là sự thật ở Tây Phương Cực Lạc Thế giới. Cho nên chúng ta đối với những người tạo tác tội nghiệp thì không dám xem thường, chúng ta nhất định phải vô cùng tôn trọng họ. Vì sao vậy? Vì một khi mà giác ngộ rồi, đến lúc lâm chung họ thật sự quay đầu trở lại sám hối nghiệp chướng của chính mình, một lòng cầu sanh Tịnh Độ, thì mười niệm thật sự có thể vãng sanh, vãng sanh đến Tây Phương Cực Lạc Thế giới có thể phẩm vị của họ còn cao hơn ta. Vì vậy, nếu chúng ta xem thường họ thì khi đến Thế giới Tây Phương Cực Lạc gặp được chắc chắn sẽ rất là xấu hổ."}, {"p": "Việc này đã có ví dụ. Vua A Xà Thế cấu kết với Đề Bà Đạt Đa phá hoại Phật pháp, tạo những tội ngũ nghịch thập ác. Đề Bà Đạt Đa đọa Địa Ngục A Tỳ, còn vua A Xà Thế đến lúc lâm chung sám hối. Ông biết mình cả đời đã gây tạo ra đều là sai, lúc lâm chung đã hối hận và phát nguyện cầu sanh Tịnh Độ. Những vị học trò này liền đi thỉnh giáo Thích Ca Mâu Ni Phật, vua A Xà Thế ngũ nghịch thập ác, ông niệm Phật vãng sanh Thế giới Cực Lạc được phẩm vị như thế nào? Thích Ca Mâu Ni Phật liền nói với mọi người, là thượng phẩm trung sanh. Việc này hoàn toàn nằm ngoài sự tưởng tượng của ta. Do đó, chúng ta mới hiểu được sức mạnh của việc sám hối không thể nghĩ bàn. Ngạn ngữ của chúng ta thường nói: “Lãng tử quay đầu còn quý hơn vàng ”. Họ thật sự mà quay đầu giác ngộ, thì họ là người tốt trong những người tốt, không thể xem thường họ được."}, {"p": "Chúng ta ngày nay học Phật đã hiểu được rồi, cũng như Đề Bà Đạt Đa, vua A Xà Thế đều là chư Phật Như Lai đang ở đó biểu diễn cho chúng ta xem, không phải là người phàm. Họ là đến để giáo hóa chúng ta, để chúng ta hiểu được pháp môn bình đẳng không có cao thấp. Bạn tu thập thiện, thọ trì ngũ giới, một đời làm người tốt, niệm Phật cũng được vãng sanh, bạn là thị hiện chính diện để dạy người hành thiện. Còn người đó thị hiện là không việc ác gì không làm, đến lúc lâm chung có thể hồi đầu sửa đổi hướng thiện, thật hiếm có được, nên cũng có thể khởi phát được với rất nhiều người tạo ác. Người tạo ác, các vị xem, họ mà hồi đầu rồi, quả báo của họ cũng không tệ, chúng ta mau mau hồi đầu, vậy là đã độ được những người không ác gì không làm rồi. Công đức đó cũng không thể nghĩ bàn. Vì vậy cách làm của Phật Bồ Tát thì chúng ta không có cách nào để mà tưởng tượng được, cho nên bất luận là họ thị hiện từ ở phương diện nào cũng đều là để lợi ích chúng sanh."}, {"p": "Ở trong “Vãng Sanh Truyện”, ở trong “Tịnh Độ Thánh Hiền Lục”, chúng ta cũng xem thấy có rất nhiều những người làm ác, đến lúc lâm chung vãng sanh thoại tướng đều vô cùng tốt. Pháp sư Oánh Kha đời nhà Tống là một ví dụ tốt trong hàng xuất gia. Ông phá giới, không giữ thanh quy, đại chúng ở trong tự viện đều xem thường đối với ông. Bản thân ông cũng đã biết, nhưng mà căn tánh hạ liệt của ông rất nặng, không cưỡng lại nổi sự mê hoặc, bản thân không có cách nào kiềm chế chính mình, vì thế nghĩ đến chính mình khởi tâm động niệm, tất cả mọi hành vi khẳng định là sẽ đọa Địa Ngục A Tỳ. Nghĩ đến sự việc này thì ông liền thấy khủng khiếp, liền thấy sợ hãi, liền thỉnh giáo với đồng liêu, với đồng tham đạo hữu có cách nào để cứu ông hay không."}, {"p": "Có một vị đồng học đã cho ông một quyển “Vãng Sanh Truyện”. Sau khi ông đọc xong thì rất cảm động, niệm A Di Đà Phật thì có thể cầu sanh Tịnh Độ, vậy thì sẽ không bị đọa địa ngục rồi. Ông tin tưởng, ông cũng thật sự có dũng khí, liền hạ quyết tâm niệm Phật để cầu Phật A Di Đà. Ông đóng cửa liêu phòng của mình lại, ở trong phòng niệm Phật suốt ba ngày ba đêm, không ăn cơm, không ngủ nghỉ, cũng không uống nước. Niệm ba ngày ba đêm thì Phật A Di Đà hiện đến, vì tâm chân thành, chân thành cầu sám hối. Phật A Di Đà nói với ông: “Dương thọ của ông vẫn còn 10 năm nữa. Từ nay trở đi, ông hãy tu hành cho tốt. Sau 10 năm nữa, đến lúc ông lâm chung ta sẽ đến để tiếp dẫn ông ”. Oánh Kha Pháp sư suy nghĩ: Không được, 10 năm bản thân ông không kiềm chế nổi sự mê hoặc, không biết là lại tạo thêm bao nhiêu tội nghiệp. Ông liền nói với Phật A Di Đà: “Mười năm thọ mạng của con con không cần nữa, con muốn đi với Ngài luôn bây giờ ”. Tâm rất khẩn thiết. Sau khi Phật A Di Đà nghe xong liền nói với ông: “Được rồi, sau ba ngày nữa ta sẽ đến tiếp dẫn ông ”. Ông vui mừng hết sức vì sau ba ngày nữa ông sẽ được vãng sanh, Phật A Di Đà đã nhận lời với ông như vậy, cho nên ngày hôm sau mở cửa ra, nói với mọi người ba ngày nữa ông sẽ vãng sanh Tịnh Độ rồi. Không có một ai tin cả, con người ông như vậy, đóng cửa lại không biết là đã làm cái gì nữa, thế mà sau ba ngày nữa ông sẽ vãng sanh Tịnh Độ sao? Nhưng thời gian của ba ngày thì không dài, được, đợi đến ba ngày nữa thì sẽ rõ."}, {"p": "Đến ngày thứ ba hôm đó, ông yêu cầu các đồng tu trong chùa mọi người niệm Phật tiễn ông vãng sanh. Mọi người rất hoan hỷ, mọi người chúng tôi niệm Phật tiễn ông xem ông có đi được hay là không. Niệm được chưa tới 15 phút, quả nhiên ông nói Phật A Di Đà đến rồi, thì liền đi với Phật A Di Đà. Ông không hề bị bệnh, cứ như vậy mà vãng sanh. Đây là sám hối vãng sanh. Bình thường không có công phu gì, ông chẳng qua chỉ là niệm ba ngày ba đêm mà thôi."}, {"p": "Chúng ta từ ở chỗ này thì có thể tin tưởng được, trên Kinh đã nói niệm một câu A Di Đà Phật thì tiêu được 80 ức kiếp sanh tử trọng tội. Nhưng phải niệm như thế nào? Thành tâm thành ý mà niệm. Như chúng ta đây chỉ có miệng niệm mà không có tâm thì không được, làm sao mà có được tác dụng lớn như vậy chứ? Như Oánh Kha Pháp sư, đó là thật, ông trong ba ngày ba đêm, mỗi câu Phật hiệu, mỗi một tiếng Phật hiệu đã tiêu được 80 ức kiếp sanh tử trọng tội. Vì sao vậy? Ông thành tâm, ông đối với thế gian này hết thảy vạn duyên đều đã thật sự buông bỏ, ông một lòng cầu vãng sanh. Chúng ta tuy rằng trong miệng có niệm Phật nhưng tâm thì vẫn đang khởi vọng tưởng, điện thoại vừa reo thì lập tức đi nghe điện thoại, liền đã quên mất Phật rồi, vậy thì làm sao mà được chứ? Đây là giả đâu phải là thật, không thể tiêu được nhiều tội nghiệp như vậy. Cho nên phải hiểu đạo lý này. Bởi vì sao mà ông niệm có hiệu quả, còn hiệu quả của chúng ta thì rất kém, không thấy được hiệu quả? Vì có nguyên nhân, tâm không như nhau, tuy rằng miệng niệm Phật nhưng tâm lại không tương đồng. Cổ đức nói, chúng ta những người niệm Phật này là “miệng niệm Di Đà tâm tán loạn, đau mồm rát họng cũng uổng công ”. Chúng ta là thuộc dạng như vậy. Đều phải hiểu được, phải rõ ràng."}, {"p": "Chúng ta đem những thói hư tật xấu cải đổi lại thì công phu của chúng ta mới đắc lực. Sau khi công phu đắc lực rồi thì tình hình sẽ có khác, bạn dù là không cầu mau chóng đi đến Thế giới Cực Lạc, bạn hiện tại sống ở thế gian này so với ở Cực Lạc không có gì khác, mỗi ngày tự mình niệm Phật nghe pháp, vì người diễn thuyết. Vì người diễn thuyết chính là giáo hóa chúng sanh. Diễn là biểu diễn, làm gương cho mọi người xem."}, {"p": "Những việc mà biểu diễn ra đều có một nguyên tắc bất biến, đó chính là đối trị phiền não tập khí của chúng sanh. Chúng sanh hiện tại ở thế gian này tạo nghiệp rộng khắp, chúng ta thị hiện không tạo ác nghiệp, bất luận là vào lúc nào, có người nhìn thấy hay không có người nhìn thấy đều như nhau. Không có người nhìn thấy thì có quỷ thần nhìn thấy. Nhất định không tạo ác nghiệp, nhất định không khởi ác niệm. Người hiện tại tự tư tự lợi, đây là gốc bệnh, chúng ta phải thị hiện đại công vô tư. Hiện tại người thế gian bất hiếu với cha mẹ, thì chúng ta phải làm gương hiếu dưỡng phụ mẫu, làm gương cho xã hội đại chúng xem. Người hiện tại không tôn trọng thầy cô, chúng ta phải thị hiện tôn trọng thầy cô. Đây chính là giáo hóa chúng sanh, dùng hành vi để mà giáo hóa. Hiện tại con người không tin lẫn nhau, hoài nghi đối với người khác, chúng ta đối với người thì tin tưởng. Họ lừa ta, ta cũng vẫn tin họ; họ hại ta, ta vẫn tin họ. Vì sao vậy? Ta muốn dạy tất cả chúng sanh tín nhiệm người khác. Ta không sợ bị hãm hại, ta cũng không sợ bị hủy báng. Vì sao vậy? Tôi làm như vậy thì sau vài năm nữa bạn sẽ hồi đầu, vì sao vậy? Vì tôi tin vào tánh bổn thiện của bạn, bạn sẽ có lương tâm, một ngày nào đó lương tâm phát lộ ra rồi, thì bạn sẽ hiểu được tôi không phải là người xấu mà tôi là người tốt, bạn làm bạn với tôi là đúng rồi, tôi không có hại bạn. Bạn hại tôi thì có thể, chứ tôi không hại bạn; bạn lừa gạt tôi thì có thể, còn tôi thì sẽ không lừa gạt bạn. Cho nên phải vì xã hội đại chúng mà làm một tấm gương tốt, không thể cứ như người trong xã hội đại chúng, người ta làm như vậy thì tôi cũng làm như vậy, người ta đi xuống tam đồ thì bạn cũng theo họ đi vào tam đồ, vậy thì bạn sai rồi, bạn không có trí huệ. Vì vậy luân lý đạo đức Hiếu - Đễ - Trung - Tín - Lễ - Nghĩa - Liêm - Sỉ chúng ta nhất định phải làm cho được. Phật dạy bảo chúng ta tam phước, tam học, lục độ, chúng ta cũng phải làm cho được."}, {"p": "Lục độ, thực tại mà nói chính là để đối trị sáu loại bệnh lớn của chúng sanh. Bố thí là đối trị xan tham. Chúng sanh không chịu tu bố thí, keo kiệt tham tài, tham không biết chán, chúng ta phải làm ra để cho họ xem. Chúng ta đối với thế xuất thế gian tất cả pháp đều không có lòng tham muốn, hoan hỷ bố thí, hoan hỷ cúng dường, càng thí càng có nhiều, càng cúng dường càng giàu thêm. Người chân thật chịu học theo Phật thì bạn sẽ có thể hiểu được, hiệu quả này bạn tự mình sẽ có được, bạn mới tin tưởng Phật nói ở trên Kinh là thật không phải là giả, mỗi câu đều là chân thật, bạn đạt được những phước báo này. Bạn bố thí tài thì được tài phú, bố thí pháp thì được thông minh trí tuệ. Khi đạt được tuyệt đối không phải tự mình hưởng thụ, khi đạt được thì nhất định phải giúp đỡ những chúng sanh nghèo khổ, có như vậy thì phước báo mới càng ngày càng lớn hơn, tích công lũy đức. Vô lượng vô biên phước huệ hiện tiền rồi, bản thân vẫn là không khởi tâm không động niệm, phước báo này cúng dường tất cả chúng sanh trong tận hư không khắp pháp giới, quyết định không có phân biệt. Người này học Phật, tôi sẽ bố thí họ; người kia không phải học Phật, bài xích Phật giáo, còn muốn tiêu diệt cả Phật giáo nữa thì càng phải bố thí cho họ, càng phải chăm lo cho họ. Vì sao vậy? Vì để làm cho ý niệm đó của họ chuyển trở lại. Cho nên nói, người như thế nào thì phải độ họ trước tiên? Người không tin tưởng Phật, người bài trừ Phật pháp là người mà chúng ta phải chăm sóc trước tiên. Vì sao mà họ bài trừ Phật pháp? Vì sao họ không tiếp nhận Phật pháp? Vì họ đối với Phật pháp không hiểu rõ, không nhận thức được, lỗi lầm không phải ở họ. Lỗi lầm là ở những người truyền dạy như chúng ta, những người học Phật như chúng ta chưa có làm được tấm gương tốt để cho họ xem. Cho nên, thật sự có thể làm được ngũ giới thập thiện thì chính là một tấm gương rất tốt. Các đồng học học Phật tại gia hay xuất gia, người người đều có thể tuân giữ ngũ giới thập thiện thì tôi tin Phật giáo ở tại thế gian này sẽ khiến cho rất nhiều rất nhiều người hiểu lầm về Phật pháp hết thảy đều quay đầu lại mà học Phật. Nếu như những gì chúng ta làm ra vẫn là thập ác, vẫn là bất thiện, người ta xem thấy cho rằng Phật giáo không thể học được rồi, tự nhiên thì họ sẽ sinh ra hiểu lầm, sinh ra bài xích. Vì vậy mà nói lỗi lầm không phải ở họ mà là ở chính mình, chúng ta tự mình làm chưa tốt, tu chưa được tốt, hoằng dương Phật pháp không đắc lực, nên mới sinh ra những sự tệ hại này."}, {"p": "Phía sau cư sĩ Hoàng Niệm Tổ đã dẫn dụng mấy câu nói của Ngẫu Ích Đại Sư, mấy câu nói này ở trong “Yếu Giải”, nói được rất hay. Ngẫu Ích Đại Sư nói: “Thập phương Phật độ, vô thử danh tướng, vô thử giai vị, vô thử pháp môn, phi tâm tính chi cực chí, trì danh chi kỳ huân, Di Đà chi đại nguyện, hà dĩ hữu thử ”. Đây là nói đến được A Duy Việt Trí quả thực là sự việc này chỉ có mỗi Thế giới Cực Lạc là có, vừa vãng sanh thì liền được rồi. Trong đời này của chúng ta có thể gặp được pháp môn này thật không phải là chuyện dễ dàng, nhất định phải biết quý trọng. Trên kệ khai Kinh nói là “trăm nghìn muôn kiếp khó tìm cầu ”, đây là nói việc chúng ta gặp được Phật pháp. Trong Phật pháp lại gặp được pháp môn Tịnh tông, thì phải thêm trăm nghìn vạn kiếp khó tìm cầu nữa. Cho nên thật sự là có nhân duyên hy hữu nên chúng ta ngày nay có thể gặp được. Chúng ta muốn vãng sanh, thật sự thành tựu ngay trong một đời này, thì đây mới gọi là thành tựu chân thật cứu cánh. Bạn ở tại thế gian, bất luận theo đuổi sự thành tựu của một ngành nghề nào cũng đều là giả. Thế gian vô thường, mặt trời rồi sẽ có ngày tắt lụi, trái đất rồi sẽ có ngày diệt vong, bạn thì có cái gì mà vĩnh viễn được cơ chứ? Không có, cho nên cái thật sự vĩnh hằng là vãng sanh Tây Phương Tịnh Độ, đây mới là sự vĩnh hằng. Chúng ta tu học vì sao mà không đắc lực? Nói lời thật lòng là chân tướng sự thật chưa nắm được rõ ràng. Thật sự nắm được rõ ràng minh bạch rồi, nếu hỏi thử bạn thế xuất thế gian tất cả những trần duyên này bạn có buông xả hay không? Đương nhiên buông xả rồi, sẽ không tiếp tục làm những thứ này nữa. Không những là người có tuổi tác cao nên buông xả, người trẻ tuổi cũng nên buông xả, vì sao vậy? Vì không kịp nữa rồi. Đây mới là một chuyện đại sự duy nhất ở trong đời này."}, {"p": "Bản thân khi bình thường tùy phần tùy lực đem pháp môn này giới thiệu cho đại chúng. Đây là nghĩa vụ và bổn phận của chúng ta, là việc phải nên làm. Cái tâm này cùng với nguyện của Phật hoàn toàn tương ưng. Hoằng nguyện của Phật A Di Đà là hy vọng tất cả chúng sanh tận hư không khắp pháp giới mau chóng thành Phật, cho nên đã xây dựng đạo tràng này ở Tây Phương Tịnh Độ để giúp đỡ hết thảy chúng sanh. Khó khăn nhất là giúp đỡ những chúng sanh mà nghiệp chướng còn chưa đoạn. Đây là một sự việc không có cách gì tưởng tượng được. Đây là đới nghiệp vãng sanh. Những người này đến Cực Lạc Thế giới đều có thể thành tựu được, vậy thì còn có ai không thể thành tựu không? Tâm của chúng ta cùng tâm của Phật như nhau. Tâm của Phật là chân thành thanh tịnh bình đẳng chánh giác từ bi, là giống như tâm của Phật, nguyện cùng với nguyện của Phật là như nhau."}, {"p": "Nguyện của Phật ở trên bộ Kinh này nói được rất rõ ràng, 48 nguyện, nguyện nguyện đều là phổ độ chúng sanh. Chúng ta đem 48 nguyện làm thành bổn nguyện của chính mình, ta cùng Phật A Di Đà là đồng tâm đồng nguyện, sau đó thì tự nhiên sẽ đồng đức đồng hạnh, vậy thì làm gì có đạo lý không vãng sanh chứ? Bản thân quả nhiên có thể đem vọng tưởng phân biệt chấp trước mà xả bỏ, chúng ta vãng sanh Thế giới Tây Phương Cực Lạc thì không phải là Phàm Thánh Đồng Cư Độ mà là Thật Báo Trang Nghiêm Độ, phàm phu chúng ta có thể làm được hay không?"}, {"p": "Cổ đức có nói, Thật Báo Trang Nghiêm Độ là Bồ Tát vãng sanh đến, Phương Tiện Hữu Dư Độ là Tiểu Thừa A La Hán vãng sanh đến, còn như muôn vàn chúng sanh như chúng ta chỉ có sanh đến Phàm Thánh Đồng Cư Độ, đây là ngày xưa có một số Đại đức đã có cách nói như vậy. Nhưng cách nói này đã bị Thiện Đạo Đại Sư phủ nhận, các vị hãy xem “Quán Vô Lượng Thọ Phật Kinh Tứ Thiếp Sớ” thì bạn sẽ biết. Thiện Đạo Đại Sư là người thời nhà Đường, là Tổ sư đời thứ hai của Tịnh Độ tông chúng ta, truyền thuyết Ngài cũng là Phật A Di Đà tái lai, vậy thì lời của Thiện Đạo Đại Sư chính là lời của A Di Đà Phật tự mình nói ra. Cách nói của Ngài thế nào? Ngài nói, tứ độ tam bối cửu phẩm vãng sanh đều ở tại gặp duyên không đồng. Sau khi chúng ta nghe xong câu nói này thì phấn khởi vô cùng. Nếu như chúng ta gặp được duyên thù thắng thì phàm phu sát đất như chúng ta cũng có thể sanh đến Thật Báo Trang Nghiêm Độ. Cho dù là Bồ Tát mà nếu không gặp được cái duyên thù thắng thì có thể là cũng sanh đến Đồng Cư Độ, hoặc giả là Phương Tiện Độ, cho nên nói là ở tại gặp duyên không đồng."}, {"p": "Duyên là gì? Thứ nhất là Kinh giáo, bạn có gặp được hay không? Đặc biệt là “Kinh Vô Lượng Thọ”, gặp được bản tốt nhất, cái này thì rất khó. Ở Trung Quốc, “Kinh Vô Lượng Thọ” có tổng cộng 12 lần phiên dịch, nhưng thật không may, trong số 12 loại này thì có 7 loại đã thất truyền, hiện tại còn truyền lại chỉ có 5 loại, mỗi một người dịch ra lại không như nhau. Có thể có được 12 loại để cho chúng ta tham khảo, thì đối với tình trạng ở Thế giới Tây Phương Cực Lạc chúng ta sẽ rõ như lòng bàn tay. Ngày xưa cũng không dễ dàng gì, Kinh sách đều là chép tay. Vào khi đó thì kỹ thuật in ấn còn chưa phát minh, là chép tay, cho nên rất dễ bị thất truyền, thế là mới có bản hội tập xuất hiện."}, {"p": "Bản hội tập đầu tiên là vào đời nhà Tống, cư sĩ Vương Nhật Hưu, Vương Long Thư đã làm. Quyển sách này của ông hiện tại cất giữ tại Long Tạng, là ở trong “Càn Long Đại Tạng Kinh”. Đây chính là quyển hội tập đầu tiên của “Kinh Vô Lượng Thọ”. Nhưng quyển hội tập này quả thật không thể làm cho mọi người hài lòng. Cư sĩ Long Thư cũng đã rất tài giỏi, ông chỉ có xem được bốn loại bản dịch gốc của “Kinh Vô Lượng Thọ”, trong “Đại Bảo Tích” của đời nhà Đường có một bộ “Vô Lượng Thọ Hội” thì ông chưa được xem, vì vậy bản hội tập của ông chỉ y cứ vào có bốn bản dịch gốc."}, {"p": "Đến những năm Hàm Phong đời Thanh, thì cư sĩ Ngụy Mạc Thâm lại làm bản hội tập lần thứ hai. Ngụy Mạc Thâm thì cả năm loại bản dịch đều xem được, đương nhiên bản hội tập của ông vượt hơn của Vương Long Thư, nhưng sự chọn lọc thì vẫn còn chưa thỏa đáng. Việc này người xưa nói là “thủ xả bất đáng ”. Ngoài ra còn có một số chữ ông đã cải đổi, đây là sự kiêng kị trong việc hội tập, vì thế Ấn Quang Đại Sư đã có sự phê bình đối với ông. Ấn Quang Đại Sư không phải phê bình hội tập là sai lầm, mà là phê bình ông đã chọn lọc những điều chưa thỏa đáng, còn đối với việc sửa đổi Kinh văn so với bản gốc thì e sợ sẽ mở ra một cái tiền lệ, về sau người ta đọc tụng Kinh Phật cảm thấy chữ này không thuận cho lắm rồi tùy tiện sửa, thế là mạnh ai nấy sửa thì sau này bản Kinh này sẽ hoàn toàn khác đi, cho nên không thể tạo ra tiền lệ như vậy được. Ngài phản đối là hai sự việc này."}, {"p": "Chính vì duyên cớ này mà những năm đầu Dân quốc, Hạ Liên Cư lão cư sĩ đã làm bản hội tập lần thứ ba, chính là quyển mà hiện tại chúng ta đang dùng. Quyển hội tập này đã đem những sự sai sót của hai bản hội tập trước mà sửa chữa trở lại, đây là một quyển “Kinh Vô Lượng Thọ” hoàn mỹ nhất. Có thể đối chiếu được với năm loại bản dịch để xem, thì bạn mới hiểu được quyển hội tập này Ngài đã làm được rất tốt. Chúng ta sâu sắc tin tưởng rằng, trong 9.000 năm Mạt Pháp, tương lai dựa vào Tịnh Độ tông để được độ thì chính là quyển Kinh văn này. Vào lúc tôi giảng Kinh, trước khi bắt đầu khai giảng thì tôi đã báo cáo tường tận với các vị rồi, vô cùng hiếm có khó gặp, cho nên chúng ta nhận thức được rõ ràng rồi thì mới hạ quyết tâm, đem thế xuất thế gian tất cả pháp vọng tưởng phân biệt chấp trước hết thảy đều buông bỏ, một lòng chuyên niệm, một môn thâm nhập huân tu lâu dài, hy vọng ngay trong một đời này khẳng định được thành tựu."}, {"p": "Câu sau cùng của phẩm này là:"}, {"h": "Kinh văn", "add": 1}, {"p": "Kinh văn: “Các tự niệm đạo, thuyết đạo, hành đạo, mạc bất hoan hỷ”."}, {"p": "Câu nói này là sự tổng kết, pháp hỷ tự tại. Người được vãng sanh đến Tây Phương Cực Lạc Thế giới, bất luận là sanh vào độ nào, sanh vào phẩm vị nào, thì người người đều pháp hỷ sung mãn. Cho nên ở tại chỗ này tôi nói với các vị đồng học, việc dạy học ở Thế giới Tây Phương Cực Lạc là một đối một, không phải là mọi người ngồi lại với nhau cùng học. Khẳng định là sự việc như vậy. Phật A Di Đà có vô lượng vô biên phân thân, Thế giới Cực Lạc có bao nhiêu người thì Ngài biến hiện thành bấy nhiêu người, một người dạy một người học, khế lý khế cơ, cho nên thành tựu mới nhanh đến như vậy. Từ chỗ này mà thể hội được lòng đại từ đại bi của Phật A Di Đà, chân thật là “Phật thị môn trung bất xả nhất nhân ”."}, {"p": "Hôm nay thời gian đã hết, chúng ta học tới đây thôi."}, {"p": "A Di Đà Phật!"}, {"p": "Cẩn dịch: Vọng Tây cư sĩ"}]});